	title.TextSize = 28
	title.Font = Enum.Font.GothamBold
	title.TextXAlignment = Enum.TextXAlignment.Center
	title.Parent = main
	
	-- Subtitle 1
	local subtitle1 = Instance.new("TextLabel")
	subtitle1.Size = UDim2.new(1, -40, 0, 18)
	subtitle1.Position = UDim2.new(0, 20, 0, 130)
	subtitle1.BackgroundTransparency = 1
	subtitle1.Text = "Click \"Get Key\" Button To Get Your Free Key"
	subtitle1.TextColor3 = Configuration.Colors.TextSec
	subtitle1.TextSize = 12
	subtitle1.Font = Enum.Font.Gotham
	subtitle1.TextXAlignment = Enum.TextXAlignment.Center
	subtitle1.Parent = main
	
	-- Premium Discord Message
	local premiumMsg = Instance.new("TextLabel")
	premiumMsg.Size = UDim2.new(1, -40, 0, 18)
	premiumMsg.Position = UDim2.new(0, 20, 0, 150)
	premiumMsg.BackgroundTransparency = 1
	premiumMsg.Text = "Premium Key Available On Discord"
	premiumMsg.TextColor3 = Configuration.Colors.Primary
	premiumMsg.TextSize = 11
	premiumMsg.Font = Enum.Font.GothamMedium
	premiumMsg.TextXAlignment = Enum.TextXAlignment.Center
	premiumMsg.Parent = main
	
	-- Subtitle 2
	local subtitle2 = Instance.new("TextLabel")
